components.css:
.ds-capability { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 1.5rem; padding-bottom: 2.75rem; border-bottom: 1px solid var(--border-subtle); }
.ds-capability__icon { width: 44px; height: 44px; display: grid; place-items: center; color: var(--primary); border: 1px solid var(--border); border-radius: 10px; background: var(--surface); }
.ds-capability__badge { font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-muted); }
